$pdo->prepare('UPDATE service_assignments SET ServiceAmount=?,DueBalance=?,PaymentStatus=?,AssignmentStatus=?,Notes=?,UpdatedAt=NOW() WHERE AssignmentID=?')->execute([$total,$due,tdc_workflow_payment_status($total,$paid),$status,$notes,$id]);tdc_reconcile_patient_due_balance($pdo,(int)$row['PatientID']);svc_redirect('assign','updated');}if($action==='assign'){
