$q=$pdo->prepare('SELECT ServiceID,DefaultAmount FROM service_subservices WHERE ServiceID=? AND IsActive=1');$q->execute([$service]);$serviceRow=$q->fetch();if(!$serviceRow)throw new RuntimeException('Selected service is unavailable.');
$gross=round((float)$serviceRow['DefaultAmount'],2);if($gross<0)throw new RuntimeException('The configured service price is invalid.');
$pdo->beginTransaction();$ref=tdc_workflow_next_reference($pdo,'service_assignments','ServiceReference','SRV');tdc_save_bill_adjustment($pdo,'Service',$ref,$gross,'None',0,0,0,'','');
