p require __DIR__ . '/../includes/notifications.php'; ?></div></div><?php require __DIR__ . '/../includes/profile.php'; ?></div></div><nav class="menu-bar"><ul class="nav-items"><?php foreach (tdc_navigation($navItems) as $item): ?><li class="nav-item<?= $item['href'] === $currentPage ? ' active' : '' ?>"><a href="<?= tdc_e($item['href']) ?>" class="nav-link"><?= tdc_navigation_icon($item['href']) ?><span><?= tdc_e($item['label']) ?></span></a></li><?php endforeach; ?></ul></nav><a href="?logout=1&csrf=<?= urlencode($csrfToken) ?>" class="logout-fab" aria-label="Log Out"><svg viewBox="0 0 20 20"><path d="M8 3H5a2 2 0 00-2 2v10a2 2 0 002 2h3"/><path d="M13 6l4 4-4 4"/><path d="M7 10h10"/></svg></a></header><main class="page-body"><div class="welcome-eyebrow">Operations</div><div class="welcome-title">Services</div><div class="welcome-sub">Manage categories, subservices and patient assignments.</div><a class="service-back" href="reception.php" title="Back to Reception"><span aria-hidden="true">←</span> Back to Reception</a><nav class="setup-section-nav"><a href="services.php?tab=categories"<?= $tab==="categories" ? " class=\"active\" aria-current=\"page\"" : "" ?>><span class="service-nav-icon" aria-hidden="true">▦</span>Category Services</a><a href="services.php?tab=subservices"<?= $tab==="subservices" ? " class=\"active\" aria-current=\"page\"" : "" ?>><span class="service-nav-icon" aria-hidden="true">☷</span>Subservices</a><a href="services.php?tab=assign"<?= $tab==="assign" ? " class=\"active\" aria-current=\"page\"" : "" ?>><span class="service-nav-icon" aria-hidden="true">↗</span>Assign Service</a></nav><?php if($notice):?><div class="success-msg"><?=$notice?></div><?php endif;?><?php if($errors):?><div class="error-msg"><ul><?php foreach($errors as $e):?><li><?=tdc_e($e)?></li><?php endforeach;?></ul></div><?php endif;?>
