<?php else:?><section class="service-panel"><h2>Assign Service</h2><button type="button" class="btn btn-success" data-open-service-modal="assignment">+ Assign Service</button><form method="post" class="service-form"><input type="hidden" name="csrf_token" value="<?=tdc_e($csrf)?>"><input type="hidden" name="action" value="assign"><div class="form-row"><select name="patient" required><option value="">Patient *</option><?php foreach($patients as $p):?><option value="<?=$p['PatientID']?>"><?=tdc_e($p['PatientName'].' — '.$p['PatientPhone'])?></option><?php endforeach;?></select><select name="doctor"><option value="">Doctor (optional)</option><?php foreach($doctors as $d):?><option value="<?=$d['DoctorID']?>"><?=tdc_e($d['DoctorName'])?></option><?php endforeach;?></select></div><div class="form-row"><select id="cat"><option value="">Category *</option><?php foreach($cats as $c):?><option value="<?=$c['ServiceCategoryID']?>"><?=tdc_e($c['CategoryName'])?></option><?php endforeach;?></select><select name="service" id="service" required><option value="">Service *</option><?php foreach($subs as $s):?><option data-cat="<?=$s['ServiceCategoryID']?>" value="<?=$s['ServiceID']?>"><?=tdc_e($s['ServiceName'])?></option><?php endforeach;?></select></div><textarea name="notes" placeholder="Optional service notes"></textarea><button class="btn btn-success">Assign Service</button></form><table class="service-table"><tr><th>Reference</th><th>Patient / Phone</th><th>Category / Service</th><th>Doctor</th><th>Total</th><th>Paid</th><th>Due</th><th>Status</th><th>Actions</th></tr><?php foreach($assignments as $a):?><tr><td><?=tdc_e($a['ServiceReference'])?></td><td><?=tdc_e($a['PatientName'])?><br><small><?=tdc_e($a['PatientPhone'])?></small></td><td><?=tdc_e($a['CategoryName'])?> / <?=tdc_e($a['ServiceName'])?></td><td><?=tdc_e($a['DoctorName']??'Unassigned')?></td><td><?=number_format((float)$a['ServiceAmount'],2)?></td><td><?=number_format((float)$a['AmountPaid'],2)?></td><td><?=number_format((float)$a['DueBalance'],2)?></td><td><?=tdc_e($a['PaymentStatus'])?></td><td class="service-actions"><button type="button" class="btn btn-secondary btn-sm" data-edit-assignment data-id="<?=$a['AssignmentID']?>" data-patient="<?=$a['PatientID']?>" data-doctor="<?=$a['DoctorID']?>" data-service="<?=$a['ServiceID']?>" data-category="<?=$a['ServiceCategoryID']?>" data-amount="<?=$a['ServiceAmount']?>" data-paid="<?=$a['AmountPaid']?>" data-status="<?=$a['AssignmentStatus']?>" data-notes="<?=tdc_e($a['Notes'])?>">Edit</button><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="action" value="delete_assignment"><input type="hidden" name="id" value="<?=$a['AssignmentID']?>"><button class="btn btn-danger btn-sm" type="submit" onclick="return confirm('Delete this unpaid assignment?')">Delete</button></form></td></tr><?php endforeach;?></table></section><?php endif;?><div class="service-modal" id="serviceModal" hidden><div class="service-modal-card"><button type="button" data-close-service-modal>×</button><h2>Service</h2><form method="post" id="categoryModalForm"><input type="hidden" name="csrf_token" value="<?=tdc_e($csrf)?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="id" value=""><input name="name" placeholder="Category name" required><textarea name="description" placeholder="Description"></textarea><button class="btn btn-success">Save Category</button></form><form method="post" id="subserviceModalForm" hidden><input type="hidden" name="csrf_token" value="<?=tdc_e($csrf)?>"><input type="hidden" name="action" value="save_subservice"><input type="hidden" name="id" value=""><select name="category" required><?php foreach($cats as $c):?><option value="<?=$c['ServiceCategoryID']?>"><?=tdc_e($c['CategoryName'])?></option><?php endforeach;?></select><input name="name" placeholder="Service name" required><input name="amount" type="number" min="0" step="0.01" placeholder="Amount" required><button class="btn btn-success">Save Subservice</button></form><form method="post" id="assignmentModalForm" hidden><input type="hidden" name="csrf_token" value="<?=tdc_e($csrf)?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="id" value=""><input type="hidden" name="status" id="modalStatusValue" value="Assigned"><label>Patient *<select name="patient" required><option value="">Choose a patient</option><?php foreach($patients as $p):?><option value="<?=$p['PatientID']?>"><?=tdc_e($p['PatientName'].' — '.$p['PatientPhone'])?></option><?php endforeach;?></select></label><label>Doctor<select name="doctor"><option value="">Choose a doctor (optional)</option><?php foreach($doctors as $d):?><option value="<?=$d['DoctorID']?>"><?=tdc_e($d['DoctorName'])?></option><?php endforeach;?></select></label><label>Category *<select id="modalCat" required><option value="">Choose a category</option><?php foreach($cats as $c):?><option value="<?=$c['ServiceCategoryID']?>"><?=tdc_e($c['CategoryName'])?></option><?php endforeach;?></select></label><label>Service *<select name="service" id="modalService" required><option value="">Choose a service</option><?php foreach($subs as $ss):?><option hidden data-cat="<?=$ss['ServiceCategoryID']?>" data-amount="<?=$ss['DefaultAmount']?>" value="<?=$ss['ServiceID']?>"><?=tdc_e($ss['ServiceName'])?></option><?php endforeach;?></select></label><label>Service Price<input id="modalAmount" type="text" value="0.00" readonly aria-describedby="servicePriceHint"><small id="servicePriceHint">Configured price; updated from the selected service.</small></label><label>Notes<textarea name="notes" placeholder="Optional service notes"></textarea></label><div id="assignmentValidation" class="form-error" hidden></div><button class="btn btn-success">Assign Service</button></form></div></div></main><script>
const sm=document.getElementById("serviceModal");
const forms={category:document.getElementById("categoryModalForm"),subservice:document.getElementById("subserviceModalForm"),assignment:document.getElementById("assignmentModalForm")};
const modalTitle=document.querySelector(".service-modal-card>h2");
function showServiceForm(kind,title){sm.hidden=false;Object.values(forms).forEach(f=>f.hidden=true);forms[kind].hidden=false;if(modalTitle)modalTitle.textContent=title;}
function resetForm(form){form.reset();const id=form.querySelector('[name="id"]');if(id)id.value='';const action=form.querySelector('[name="action"]');if(action)action.value=kindAction(form);}
function kindAction(form){return form===forms.category?'save_category':form===forms.subservice?'save_subservice':'assign';}
function setAssignmentFieldsDisabled(disabled){['patient','doctor'].forEach(n=>{const el=mform?.querySelector('[name="'+n+'"]');if(el)el.disabled=disabled;});if(mc)mc.disabled=disabled;if(ms)ms.disabled=disabled;}document.querySelectorAll("[data-open-service-modal]").forEach(b=>b.onclick=()=>{const kind=b.dataset.openServiceModal;showServiceForm(kind,kind==='category'?'Add Category':kind==='subservice'?'Add Subservice':'Assign Service');resetForm(forms[kind]);if(kind==='assignment')setAssignmentFieldsDisabled(false);});
const serviceClose=document.querySelector("[data-close-service-modal]");if(serviceClose){serviceClose.setAttribute('aria-label','Close service dialog');serviceClose.setAttribute('title','Close');serviceClose.onclick=()=>sm.hidden=true;}
const categoryForm=forms.category,subserviceForm=forms.subservice;
document.querySelectorAll("[data-edit-category]").forEach(b=>b.onclick=()=>{showServiceForm('category','Edit Category');categoryForm.querySelector('[name="id"]').value=b.dataset.id;categoryForm.querySelector('[name="name"]').value=b.dataset.name||'';categoryForm.querySelector('[name="description"]').value=b.dataset.description||'';});
document.querySelectorAll("[data-edit-subservice]").forEach(b=>b.onclick=()=>{showServiceForm('subservice','Edit Subservice');subserviceForm.querySelector('[name="id"]').value=b.dataset.id;subserviceForm.querySelector('[name="category"]').value=b.dataset.category;subserviceForm.querySelector('[name="name"]').value=b.dataset.name||'';subserviceForm.querySelector('[name="amount"]').value=b.dataset.amount||'';subserviceForm.querySelector('[name="description"]').value=b.dataset.description||'';});
const c=document.getElementById('cat'),s=document.getElementById('service');if(c&&s){c.onchange=()=>{[...s.options].forEach(o=>o.hidden=o.value&&o.dataset.cat!==c.value);s.value='';};}
const mc=document.getElementById('modalCat'),ms=document.getElementById('modalService'),mt=document.getElementById('modalAmount'),mform=forms.assignment,merr=document.getElementById('assignmentValidation');
function filterModalServices(){if(!ms||!mc)return;[...ms.options].forEach(o=>{o.hidden=!o.value||o.dataset.cat!==mc.value;});}
function syncServicePrice(){if(!ms||!mt)return;const selected=ms.selectedOptions[0];mt.value=selected&&selected.value?Number(selected.dataset.amount||0).toFixed(2):'0.00';}
if(mc){mc.onchange=()=>{filterModalServices();ms.value='';syncServicePrice();};ms.onchange=syncServicePrice;}
document.querySelectorAll("[data-edit-assignment]").forEach(b=>b.onclick=()=>{showServiceForm('assignment','Edit Assigned Service');setAssignmentFieldsDisabled(true);const id=mform.querySelector('[name="id"]'),action=mform.querySelector('[name="action"]');id.value=b.dataset.id;action.value='update_assignment';mform.patient.value=b.dataset.patient||'';mform.doctor.value=b.dataset.doctor||'';mc.value=b.dataset.category||'';filterModalServices();ms.value=b.dataset.service||'';syncServicePrice();document.getElementById('modalStatusValue').value=b.dataset.status||'Assigned';mform.notes.value=b.dataset.notes||'';});
if(mform){mform.onsubmit=e=>{if(!mform.patient.value||!mc.value||!ms.value){e.preventDefault();merr.hidden=false;merr.textContent='Please choose a patient, category and service.';}};}</script></body></html>
